/**
 * Cedros Login Admin Plugin
 *
 * Exports the cedrosLoginPlugin for use with AdminShell.
 * Provides user management, deposits, withdrawals, and configuration sections.
 */

import { lazy } from 'react';
import type { AdminPlugin, HostContext, PluginContext, AdminSectionConfig } from './types';
import { Icons } from './icons';

// ============================================================================
// Lazy-loaded Section Components
// ============================================================================

const UsersSection = lazy(() => import('./sections/UsersSection'));
const TeamSection = lazy(() => import('./sections/TeamSection'));
const DepositsSection = lazy(() => import('./sections/DepositsSection'));
const WithdrawalsSection = lazy(() => import('./sections/WithdrawalsSection'));
const AuthenticationSettings = lazy(() => import('./sections/AuthenticationSettings'));
const EmbeddedWalletSettings = lazy(() => import('./sections/EmbeddedWalletSettings'));
const EmailSettings = lazy(() => import('./sections/EmailSettings'));
const WebhookSettings = lazy(() => import('./sections/WebhookSettings'));
const CreditSystemSettings = lazy(() => import('./sections/CreditSystemSettings'));
const ServerSettings = lazy(() => import('./sections/ServerSettings'));

// ============================================================================
// Permission Mapping
// ============================================================================

type LoginPermission =
  | 'login:users:read'
  | 'login:users:write'
  | 'login:members:read'
  | 'login:members:write'
  | 'login:invites:read'
  | 'login:invites:write'
  | 'login:deposits:read'
  | 'login:deposits:write'
  | 'login:settings:read'
  | 'login:settings:write';

/**
 * Maps plugin permissions to org-level permissions/roles.
 */
const PERMISSION_MAP: Record<LoginPermission, string[]> = {
  'login:users:read': ['admin', 'owner'],
  'login:users:write': ['admin', 'owner'],
  'login:members:read': ['member:read', 'admin', 'owner'],
  'login:members:write': ['member:remove', 'member:role_change'],
  'login:invites:read': ['invite:read', 'admin', 'owner'],
  'login:invites:write': ['invite:create', 'invite:cancel'],
  'login:deposits:read': ['admin', 'owner'],
  'login:deposits:write': ['admin', 'owner'],
  'login:settings:read': ['admin', 'owner'],
  'login:settings:write': ['admin', 'owner'],
};

// ============================================================================
// Section Configuration
// ============================================================================

