import { useMemo, type JSX } from 'react';
import type { AdminShellSectionWrapper, HostContext } from '@cedros/data-react/admin';
import {
  AuthStateContext,
  AuthUIContext,
  CedrosLoginContext,
  type AuthStateContextValue,
  type AuthUIContextValue,
  type CedrosLoginContextValue,
} from '../context/CedrosLoginContext';
import { getDefaultFeatureFlags, isFeatureEnabled as resolveFeatureEnabled } from '../featureFlags';
import type { AuthUser, CedrosLoginConfig } from '../types';

const NOOP = () => {};
const NOOP_ASYNC = async () => {};

function buildCedrosLoginContextValue(hostContext: HostContext): CedrosLoginContextValue | null {
  const cedrosLogin = hostContext.cedrosLogin;
  if (!cedrosLogin) {
    return null;
  }

  const featureFlags = getDefaultFeatureFlags();
  const user: AuthUser | null = cedrosLogin.user
    ? {
        authMethods: [],
        emailVerified: false,
        createdAt: '',
        updatedAt: '',
        ...cedrosLogin.user,
      }
    : null;
  const config: CedrosLoginConfig = {
    serverUrl: cedrosLogin.serverUrl,
  };

  return {
    config,
    featureFlags,
    isFeatureEnabled: (name) => resolveFeatureEnabled(name, { flags: featureFlags }),
    user,
    authState: user ? 'authenticated' : 'unauthenticated',
    error: null,
    logout: NOOP_ASYNC,
    refreshUser: NOOP_ASYNC,
    isModalOpen: false,
    openModal: NOOP,
    closeModal: NOOP,
    _internal: {
      handleLoginSuccess: NOOP,
      getAccessToken: cedrosLogin.getAccessToken,
      getReferralCode: () => null,
    },
  };
}

export const CedrosLoginAdminSectionWrapper: AdminShellSectionWrapper = ({
  children,
  hostContext,
}): JSX.Element => {
  const combinedValue = useMemo(
    () => buildCedrosLoginContextValue(hostContext),
    [hostContext]
  );

  if (!combinedValue) {
    return <>{children}</>;
  }

  const { error, isModalOpen, openModal, closeModal, ...authStateValue } = combinedValue;
  const uiValue: AuthUIContextValue = {
    error,
    isModalOpen,
    openModal,
    closeModal,
  };

  return (
    <AuthStateContext.Provider value={authStateValue as AuthStateContextValue}>
      <AuthUIContext.Provider value={uiValue}>
        <CedrosLoginContext.Provider value={combinedValue}>{children}</CedrosLoginContext.Provider>
      </AuthUIContext.Provider>
    </AuthStateContext.Provider>
  );
};
